using HotChocolate.Authorization;
using GraphApi.Infrastructure.Services;using GraphApi.Models.FNZ.DocumentosTransaccion;using GraphApi.Services.FNZ.DocumentosTransaccion;using HotChocolate;using System.Linq;namespace GraphApi.GraphQL.FNZ.DocumentosTransaccion{    [MutationType]    [GraphQLDescription("Punto de entrada para las mutaciones de DocumentosTransaccions: creación, actualización y eliminación.")]    public class DocumentosTransaccionMutation    {        [Authorize]        [GraphQLName("createDocumentosTransaccion")]        [GraphQLDescription("Crea un nuevo DocumentosTransaccion usando los headers 'UserID' y 'WindowName'.")]        public async Task<clReadDocumentosTransaccion> CreateDocumentosTransaccionAsync(            [GraphQLDescription("Datos necesarios para crear el DocumentosTransaccion.")]            clCreateDocumentosTransaccion objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de DocumentosTransaccion.")]            IDocumentosTransaccionService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.CreateDocumentosTransaccion(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("updateDocumentosTransaccion")]        [GraphQLDescription("Actualiza los campos especificados de un DocumentosTransaccion existente.")]        public async Task<clReadDocumentosTransaccion?> UpdateDocumentosTransaccionAsync(            [GraphQLDescription("Datos del DocumentosTransaccion a actualizar.")]            clUpdateDocumentosTransaccion objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de DocumentosTransaccion.")]            IDocumentosTransaccionService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.UpdateDocumentosTransaccion(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("deleteDocumentosTransaccion")]        [GraphQLDescription("Elimina un DocumentosTransaccion por su ID.")]        public async Task<bool> delDocumentosTransaccionAsync(            [GraphQLDescription("ID del DocumentosTransaccion a eliminar.")]            int nDocumentosTransaccionID,            [Service]            [GraphQLDescription("Servicio para operaciones de DocumentosTransaccion.")]            IDocumentosTransaccionService objService        )        {            return await objService.DeleteDocumentosTransaccion(nDocumentosTransaccionID);        }    }}